Under Assumptions~\ref{singleeigenvalue} and \ref{as:pstar}, with the choice of $\tilde{c} = 2\pfactorc (4\sqrt{d} + 2\log (2T/\alpha))$ in \eqref{eq:OSL-estimator}, Algorithm \ref{LDP-Single} with OLS mechanism $\psi^{OLS}_{t}$ and estimator $\varphi_{t}^{OLS}$ achieve the following regret with probability at least $1-\alpha$ for some constant $C$,
	\begin{align*}
		\text{Reg}(T)
		& \le C \sqrt{T} (\CB (\pfactorc +\sigma_{\epsilon}) d \frac{\sqrt{(d+\log(T/\alpha))\log (KT/\alpha)}}{\kappa_lp_{*}} + o(1))
	\end{align*}

Under Assumptions~\ref{assump:link}--\ref{as:pstar}, with the choice of $\eta_t = c' d/(\kappa_l \zeta p_{*}t)$ for some $c'>1$ in \eqref{eq:SGD-estimator}, Algorithm~\ref{LDP-Single} with SGD mechanism $\psi^{SGD}_{t}$ and estimator $\varphi_{t}^{SGD}$ achieves the following regret with probability at least $1-\alpha$ for some constant $C$, \begin{align*}
		\text{Reg}(T)
		\le C \sqrt{T}(\frac{r_{\varepsilon, d}\sqrt{d}}{\zeta \kappa_l p_{*}} \log\log(T/\alpha) + o(1)).
	\end{align*}

Under Assumptions~\ref{singleeigenvalue}--\ref{margin-condition-single} with the same choice of $\tilde{c}$ in Theorems~\ref{ub-single-worst}, 
	Algorithm \ref{LDP-Single} with OLS mechanism $\psi^{OLS}_{t}$ and estimator $\varphi_{t}^{OLS}$ achieves the following regret with probability at least $1-\alpha$ for some constant $C$,
\begin{align*}
	\text{Reg}(T)\leq C\cdot \left\{
		\begin{array}{ll}
		{\gamma \CB}\log T[ (\dfrac{\CB d ( \CB \sigma_\epsilon+\pfactorc )\sqrt{d+\log(T/\alpha)} }{\kappa_l p_*})^2+o_{\beta,\gamma}(1)], &\beta = 1,

Under Assumptions~\ref{assump:link}--\ref{margin-condition-single} and  with the same choice of $\eta_t$ in Theorems~\ref{ub-single-worst}, 
	Algorithm \ref{LDP-Single} with SGD mechanism $\psi^{SGD}_{t}$ and estimator $\varphi_{t}^{SGD}$ achieves the following regret with probability at least $1-\alpha$ for some constant $C$,
	\begin{align*}
	\text{Reg}(T)\leq C\cdot 
	\left\{
		\begin{array}{ll}
			{\gamma L\CB} \log T [(\dfrac{r_{\varepsilon,d} L d\CB\sqrt{\log(\log(T)/\alpha)} }{\zeta\kappa_l p_*})^2+o_{\beta,\gamma}(1)], &\beta = 1,

\text{Reg}(T)\leq C\cdot \gamma L \CB
	\Big[ 
		\big(
			\dfrac{Kr_{\varepsilon,d} L\CB\sqrt{\log((TK\log T)/\alpha)} }{\zeta\kappa_l p'}
		\big)^{1+\beta} 
		+o_{h_\text{sub},\beta,\gamma}(1)
	\Big]
	\cdot 
	\left\{
		\begin{array}{ll}
			\log T , &\beta = 1,\\
			\dfrac{T^{\frac{1-\beta}{2}}	}{1-\beta}, &0<\beta <1.
		\end{array}
	\right.
